      "content": "{\n\t\"name\": \"dsh-dream-skin\",\n\t\"version\": \"10.29.0\",\n\t\"description\": \"DeepSeek Harness 换肤插件（Dream Skin for DSH）：8 套 iOS / Linear 式清透冷调的高质感主题 + 弥散光壁纸 + 每皮肤智能背景 + 强调色 + 主题包分享，把换肤做成材质与配色克制的高级感工艺，而非贴图。Works in native DSH Web and third-party desktop clients (DSH Desktop): 8 original premium themes, glass materials, wallpaper 2.0, per-user accent, shareable theme packs — purely native token system.\",\n\t\"license\": \"MIT\",\n\t\"type\": \"module\",\n\t\"main\": \"lib/index.js\",\n\t\"types\": \"lib/types/index.d.ts\",\n\t\"icon\": \"./icon.svg\",\n\t\"exports\": {\n\t\t\".\": {\n\t\t\t\"types\": \"./lib/types/index.d.ts\",\n\t\t\t\"default\": \"./lib/index.js\"\n\t\t},\n\t\t\"./client\": {\n\t\t\t\"types\": \"./lib/types/client/index.d.ts\",\n\t\t\t\"default\": \"./lib/client.js\"\n\t\t},\n\t\t\"./package.json\": \"./package.json\",\n\t\t\"./locale/en.json\": \"./locale/en.json\",\n\t\t\"./locale/zh.json\": \"./locale/zh.json\"\n\t},\n\t\"files\": [\n\t\t\"icon.svg\",\n\t\t\"locale\",\n\t\t\"lib/index.js\",\n\t\t\"lib/client.js\",\n\t\t\"lib/types\",\n\t\t\"cordis.patch.yml\",\n\t\t\"README.md\",\n\t\t\"docs/examples\",\n\t\t\"docs/themes-spec.md\",\n\t\t\"docs/evidence/dsh-store-1411-followup-2026-10-15.md\"\n\t],\n\t\"author\": \"dsh-dream-skin contributors\",\n\t\"repository\": {\n\t\t\"type\": \"git\",\n\t\t\"url\": \"git+https://github.com/RevolutionLA/dsh-dream-skin.git\"\n\t},\n\t\"bugs\": {\n\t\t\"url\": \"https://github.com/RevolutionLA/dsh-dream-skin/issues\"\n\t},\n\t\"homepage\": \"https://github.com/RevolutionLA/dsh-dream-skin#readme\",\n\t\"keywords\": [\n\t\t\"deepseek\",\n\t\t\"deepseek-harness\",\n\t\t\"dsh\",\n\t\t\"dsh-desktop\",\n\t\t\"dsh-plugin\",\n\t\t\"plugin\",\n\t\t\"theme\",\n\t\t\"skin\",\n\t\t\"wallpaper\",\n\t\t\"theme-pack\",\n\t\t\"glassmorphism\",\n\t\t\"web-ui\",\n\t\t\"换肤\",\n\t\t\"主题\",\n\t\t\"美化\"\n\t],\n\t\"engines\": {\n\t\t\"node\": \">=18\"\n\t},\n\t\"scripts\": {\n\t\t\"test\": \"node --test tests/*.test.cjs\",\n\t\t\"repo:eol\": \"node scripts/normalize-eol.cjs\",\n\t\t\"skin:generate\": \"node scripts/apply-skin-system.cjs\",\n\t\t\"skin:check\": \"node scripts/apply-skin-system.cjs --check\",\n\t\t\"skin:audit\": \"node scripts/skin-audit.cjs\",\n\t\t\"craft:audit\": \"node scripts/craft-audit.cjs\",\n\t\t\"host:census\": \"node scripts/host-consumers.cjs\",\n\t\t\"host:census:check\": \"node scripts/host-consumers.cjs --check\",\n\t\t\"host:preflight\": \"node scripts/host-preflight.cjs\",\n\t\t\"previews\": \"node scripts/generate-skin-mockups.cjs\",\n\t\t\"previews:check\": \"node scripts/generate-skin-mockups.cjs --check\",\n\t\t\"typecheck\": \"npx -y -p typescript@5.6.3 tsc -p tsconfig.json\",\n\t\t\"wash:check\": \"node scripts/wash-cascade.cjs\",\n\t\t\"compositor:audit\": \"node scripts/compositor-audit.cjs\"\n\t},\n\t\"dsh\": {\n\t\t\"bundle\": {\n\t\t\t\"patch\": \"./cordis.patch.yml\"\n\t\t},\n\t\t\"client\": {\n\t\t\t\"inject\": [\n\t\t\t\t\"@deepseek-ai/dsh-client-runtime\",\n\t\t\t\t\"@deepseek-ai/dsh-client-locale\",\n\t\t\t\t\"@deepseek-ai/dsh-client-ui-theme\",\n\t\t\t\t\"@deepseek-ai/dsh-client-ui-settings\",\n\t\t\t\t\"@deepseek-ai/dsh-client-ui-settings-general\"\n\t\t\t],\n\t\t\t\"platform\": \"web\",\n\t\t\t\"immediately\": true\n\t\t}\n\t},\n\t\"peerDependencies\": {\n\t\t\"@deepseek-ai/cordis\": \"^4.0.1 || >=4.0.5-0 <5\",\n\t\t\"@deepseek-ai/dsh-client-locale\": \">=0.1.0-rc.6 <0.3.0-0\",\n\t\t\"@deepseek-ai/dsh-client-runtime\": \">=0.1.0-rc.6 <0.3.0-0\",\n\t\t\"@deepseek-ai/dsh-client-store\": \">=0.1.0-rc.6 <0.3.0-0\",\n\t\t\"@deepseek-ai/dsh-client-ui-settings\": \">=0.1.0-rc.6 <0.3.0-0\",\n\t\t\"@deepseek-ai/dsh-client-ui-settings-general\": \">=0.1.0-rc.6 <0.3.0-0\",\n\t\t\"@deepseek-ai/dsh-client-ui-theme\": \">=0.1.0-rc.6 <0.3.0-0\",\n\t\t\"react\": \"^18.2.0\"\n\t},\n\t\"peerDependenciesMeta\": {\n\t\t\"@deepseek-ai/cordis\": {\n\t\t\t\"optional\": true\n\t\t},\n\t\t\"@deepseek-ai/dsh-client-locale\": {\n\t\t\t\"optional\": true\n\t\t},\n\t\t\"@deepseek-ai/dsh-client-runtime\": {\n\t\t\t\"optional\": true\n\t\t},\n\t\t\"@deepseek-ai/dsh-client-store\": {\n\t\t\t\"optional\": true\n\t\t},\n\t\t\"@deepseek-ai/dsh-client-ui-settings\": {\n\t\t\t\"optional\": true\n\t\t},\n\t\t\"@deepseek-ai/dsh-client-ui-settings-general\": {\n\t\t\t\"optional\": true\n\t\t},\n\t\t\"@deepseek-ai/dsh-client-ui-theme\": {\n\t\t\t\"optional\": true\n\t\t},\n\t\t\"react\": {\n\t\t\t\"optional\": true\n\t\t}\n\t}\n}\n"
