ceeded. Only the\n\t\t\t\t// transition back to healthy republishes, so the happy path costs nothing.\n\t\t\t\tif (lastStorageError !== null) {\n\t\t\t\t\tlastStorageError = null;\n\t\t\t\t\ttry { publishStatus(); } catch {}\n\t\t\t\t}\n\t\t\t\treturn true;\n\t\t\t} catch (e) {\n\t\t\t\tlastStorageError = {\n\t\t\t\t\tkey,\n\t\t\t\t\tmessage: (e && e.message) || String(e),\n\t\t\t\t\tname: (e && e.name) || null,\n\t\t\t\t\tat: Date.now()\n\t\t\t\t};\n\t\t\t\t// Re-publish NOW. The snapshot object is replaced rather than mutated, so without\n\t\t\t\t// this the field would only show up the next time something else happened to\n\t\t\t\t// publish — which for a user whose quota filled at boot could mean never.\n\t\t\t\ttry { publishStatus(); } catch {}\n\t\t\t\treturn false;\n\t\t\t}\n\t\t}\n\n\t\tfunction readStorage(key) {\n\t\t\tif (stateCache.has(key)) return stateCache.get(key);\n\t\t\tlet value = null;\n\t\t\ttry {\n\t\t\t\tvalue = window.localStorage.getItem(key);\n\t\t\t} catch {\n\t\t\t\t// storage unavailable\n\t\t\t}\n\t\t\tstateCache.set(key, value);\n\t\t\treturn value;\n\t\t}\n\n\t\t/**\n\t\t * The OS preference that \"automatic\" reads. Chromium maps the system's\n\t\t * reduce-transparency accessibility setting onto this media feature; a DOM\n\t\t * without `matchMedia` (or without the feature) returns null and automatic\n\t\t * resolves to the shipped look, which is the same answer as \"no preference\".\n\t\t */\n\t\tfunction reducedTransparencyQuery() {\n\t\t\ttry {\n\t\t\t\tif (typeof window !== \"object\" || typeof window.matchMedia !== \"function\") return null;\n\t\t\t\tconst mql = window.matchMedia(REDUCED_TRANSPARENCY_QUERY);\n\t\t\t\treturn mql && typeof mql.matches === \"boolean\" ? mql : null;\n\t\t\t} catch {\n\t\t\t\treturn null;\n\t\t\t}\n\t\t}\n\n\t\t/** Whether the user has pinned the switch, as opposed to leaving it automatic. */\n\t\tfunction isPerformanceExplicit() {\n\t\t\tconst stored = readStorage(PERFORMANCE_KEY);\n\t\t\treturn st